/* Group approval business migrated from zhongtai; PC owns rendering and storage. */
(function(){
'use strict';
const E=GroupEngine,T=E.T,KEY='weid.pc.group-approval.v1',params=new URLSearchParams(location.search),$=s=>document.querySelector(s);
const actor='admin';
let state,route=[],mobile=params.get('groupMobile')==='1',timer,modal=null,lastFocus,applicationDraft=null,serial=Promise.resolve(),listPage=1,listSize=10,listTab='',filters={q:'',status:'',company:'',template:'',from:'',to:''};
const A=window.GA={E,KEY,views:{},actions:{},forms:{},get state(){return state;},get actor(){return actor;},get mobile(){return mobile;},get route(){return route;},get modal(){return modal;},get draft(){return applicationDraft;}};
const esc=A.esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=A.date=x=>x?new Date(x).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).replaceAll('/','-'):'—';
const money=A.money=x=>'¥'+Number(x||0).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
const companyName=A.companyName=c=>E.company(state,c)?.short||'—',personName=A.personName=p=>p==='system'?'系统':E.person(state,p)?.name||'—',deptName=A.deptName=d=>E.department(state,d)?.name||'—';
const paths={home:'M3 10l9-7 9 7M5 9v12h14V9M9 21v-8h6v8',list:'M8 4h12v17H4V4h4M8 2h8v5H8zM8 12h8M8 16h5',rule:'M4 5h16M4 12h16M4 19h16M8 3v4M16 10v4M10 17v4',org:'M9 3h6v5H9zM3 16h6v5H3zM15 16h6v5h-6zM12 8v4M6 16v-4h12v4',chart:'M4 3v18h17M8 16v-4M13 16V7M18 16v-7',phone:'M7 2h10a1 1 0 0 1 1 1v18H6V3a1 1 0 0 1 1-1M10 18h4',bell:'M18 8a6 6 0 0 0-12 0v6l-2 3h16l-2-3V8M10 21h4',person:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M4 21v-3a8 8 0 0 1 16 0v3',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',filter:'M4 6h16M7 12h10M10 18h4',plus:'M12 4v16M4 12h16',arrow:'M15 5l-7 7 7 7',empty:'M5 3h10l4 4v14H5zM15 3v5h4M8 13h8M8 17h5',check:'M5 12l4 4L19 6'};
const icon=A.icon=(name)=>`<svg class="ico" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.list}"/></svg>`;
const btn=A.btn=(text,action,extra='',cls='')=>`<button type="button" class="btn ${cls} ${cls.includes('quiet')?'text':''}" data-action="${action}" ${extra}>${text}</button>`;
const link=A.link=(text,to,cls='quiet compact blue')=>btn(text,'go',`data-to="${esc(to)}"`,cls);
const badge=A.badge=(status,label)=>`<span class="pill ${({approved:'green',pending:'blue',handling:'blue',active:'blue',returned:'orange',rejected:'red'})[status]||''}">${esc(label||E.STATUS[status]||status)}</span>`;
const opts=A.opts=(rows,value)=>rows.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('');
const input=A.input=(label,name,value='',extra='',type='text')=>`<label class="field"><span class="field-title">${label}</span><input type="${type}" name="${name}" aria-label="${esc(label.replace(/<[^>]+>/g,''))}" value="${esc(value)}" ${extra}></label>`;
const select=A.select=(label,name,rows,value='',extra='')=>`<label class="field"><span class="field-title">${label}</span><select name="${name}" aria-label="${esc(label.replace(/<[^>]+>/g,''))}" ${extra}>${opts(rows,value)}</select></label>`;
const textarea=A.textarea=(label,name,value='',extra='')=>`<label class="field"><span class="field-title">${label}</span><textarea name="${name}" aria-label="${esc(label.replace(/<[^>]+>/g,''))}" ${extra}>${esc(value)}</textarea></label>`;
const check=A.check=(label,name,checked)=>`<div class="ga-check-line"><label class="check-row"><input type="checkbox" name="${name}" ${checked?'checked':''}>${label}</label></div>`;
const empty=A.empty=(title,desc='',actions='')=>`<div class="ga-empty">${icon('empty')}<h3>${title}</h3>${desc?`<p>${desc}</p>`:''}${actions}</div>`;
const panel=A.panel=(title,body,action='')=>`<section class="panel"><div class="panel-head"><h3>${title}</h3>${action}</div><div class="panel-body">${body}</div></section>`;
const names=A.names=members=>members.map(personName).join('、');
const visible=A.visible=()=>state.requests.filter(r=>E.canView(state,actor,r));
const deny=A.deny=()=>empty('暂无访问权限','该记录不存在或当前不可访问。',link('返回工作台','workbench'));
A.load=function(){state=PCGroupStorage.current;return state;};
A.mutate=function(fn){const task=async()=>{const fresh=await PCGroupStorage.read(),version=fresh.revision,working=E.clone(fresh),result=await fn(working);if(result?.unchanged===true){state=PCGroupStorage.current;return result;}working.revision=version+1;await PCGroupStorage.write(working,version);state=PCGroupStorage.current;return result;};const result=serial.then(task);serial=result.catch(()=>{});return result;};
A.toast=message=>toast(message);
A.close=function(){if(!modal)return;modal=null;PCGroupUI.close();};
A.open=function(title,body,onSave=null,options={}){modal={title,onSave};PCGroupUI.open(title,body,onSave,options);};
A.confirm=function(title,body,fn,saveText='确认'){const previous=modal;modal={title};PCGroupUI.confirm(title,body,async()=>{await fn();A.close();A.render();},saveText,()=>{modal=previous;});};
A.go=function(to){if(A.beforeNavigate?.(to)===false)return;if(applicationDraft?.dirty&&['apply','edit'].includes(route[0])&&to!==route.join('/')){const target=to;A.open('离开申请表','<p class="detail-text">当前申请有未提交的修改，离开前可保存草稿。</p>',applicationDraft.id&&state.requests.find(r=>r.id===applicationDraft.id)?.status==='returned'?null:async()=>{A.captureApplication();await A.mutate(s=>E.submit(s,actor,E.clone(applicationDraft),true));applicationDraft=null;A.close();A.go(target);},{saveText:'保存草稿并离开',footer:btn('放弃修改并离开','application-discard',`data-to="${esc(target)}"`,'quiet red')});return;}PCGroupUI.navigate(to);};
A.render=function(){const pages={workbench:['审批工作台','home'],list:['审批列表','list'],rules:['规则配置','rule'],rule:['规则配置','rule'],organization:['组织与人员','org'],statistics:['审批统计','chart'],demo:['移动端演示','phone'],catalog:['发起审批','plus'],apply:['发起审批','plus'],edit:['修改申请','list'],detail:['审批详情','list'],notifications:['消息通知','bell'],profile:['我的','person']};const title=pages[route[0]]?.[0]||'集团审批';document.title=title+' · 集团审批';let content='';try{content=(A.views[route[0]]||A.views.workbench)();}catch(e){content=empty('页面暂时无法显示',esc(e.message),link('返回工作台','workbench'));console.error(e);}
 if(mobile){
  document.body.classList.add('ga-mobile-mode');
  const mainPages=['workbench','list','catalog','profile'],backTo=['apply','edit'].includes(route[0])?'catalog':route[0]==='detail'?'list/all':'workbench';
  const mobileTitle=['apply','edit'].includes(route[0])&&applicationDraft?applicationDraft.schema.basic.name:route[0]==='list'&&route[1]==='overdue'?'超时待办':title;
  const left=mainPages.includes(route[0])?link(icon('bell'),'notifications','quiet ga-header-icon'):btn(icon('arrow')+'返回','go',`data-to="${backTo}"`,'quiet ga-header-back');
  const right=['workbench','list'].includes(route[0])?btn(icon('plus')+'发起','go','data-to="catalog" aria-label="发起审批"','quiet ga-header-create'):route[0]==='notifications'?btn('全部已读','notice-read-all','aria-label="全部标为已读"','quiet ga-header-read'):'<span></span>';
  const activePage=['apply','edit'].includes(route[0])?'catalog':route[0]==='detail'?'list':route[0];
  $('#ga-application').innerHTML=`<main class="ga-mobile" data-mobile-page="${esc(route[0])}"><header class="ga-mobile-header"><div class="ga-header-side">${left}</div><h1>${esc(mobileTitle)}</h1><div class="ga-header-side">${right}</div></header><div class="ga-mobile-content">${content}</div><nav class="ga-mobile-nav" aria-label="移动端导航">${[['workbench','home','工作台'],['catalog','plus','发起'],['list/all','list','审批'],['profile','person','我的']].map(([to,i,l])=>`<button class="${to.split('/')[0]===activePage?'active':''}" ${to.split('/')[0]===activePage?'aria-current="page"':''} data-action="go" data-to="${to}">${icon(i)}${l}</button>`).join('')}</nav></main>`;
  $('#ga-application .ga-header-icon')?.setAttribute('aria-label','消息通知');
 }else PCGroupUI.render(content,title,route);PCGroupUI.prepare();A.afterRender?.();};
A.enter=function(){route=PCGroupUI.readRoute();if(!['apply','edit'].includes(route[0]))applicationDraft=null;A.load();PCGroupUI.ensure();A.render();};
A.views.workbench=function(){const u=E.person(state,actor),rs=visible(),todo=rs.filter(r=>E.pendingFor(r,actor)),mine=rs.filter(r=>r.applicant===actor),done=rs.filter(r=>r.events.some(e=>e.actor===actor&&['同意审批','完成办理'].includes(e.action))),over=todo.filter(r=>T.overdue(r));const types=state.templates.filter(t=>E.allowed(state,actor,t));const stat=(label,n,desc,to,color='blue')=>`<button class="stat" data-action="go" data-to="${to}"><span class="muted small">${label}</span><strong class="${color}">${n}</strong>${!mobile?`<small>${desc}</small>`:''}</button>`;return `<div class="ga-summary">${stat('待我处理',todo.length,'审批与办理待办','list/todo')}${stat('我发起的',mine.length,'追踪申请处理进度','list/mine','')}${stat('我已处理',done.length,'查看历史处理记录','list/done','green')}${stat('超时待办',over.length,'请优先处理','list/overdue','red')}</div><div class="ga-grid"><div class="stack">${contentModule('常用审批',`<div class="panel-body"><div class="ga-types">${types.slice(0,6).map(typeCard).join('')}</div></div>`,link('全部事项 ›','catalog')+(!mobile?link('＋ 发起审批','catalog','primary'):''))}<section class="panel"><div class="panel-head"><h3>待我处理 <span class="muted small">${todo.length}</span></h3>${link('查看全部 ›','list/todo')}</div>${todo.slice(0,5).map(todoRow).join('')||empty('暂无待办',mobile?'':'当前没有需要处理的审批。')}</section></div><div class="stack">${panel('我的申请',mine.slice(0,4).map(r=>`<div class="ga-section"><div class="row between">${link(esc(r.title),'detail/'+r.id)}${badge(r.status)}</div><span class="ga-sub">${date(r.createdAt)} · ${esc(companyName(r.company))}</span></div>`).join('')||'<p class="muted small">暂无申请</p>',link('全部 ›','list/mine'))}${panel('消息通知',state.notifications.filter(n=>n.person===actor).slice(0,4).map(n=>`<div class="ga-section">${btn(esc(n.title),'notice-open',`data-id="${n.id}"`,'quiet compact blue')}<span class="ga-sub">${date(n.at)}${!n.read?' · 未读':''}</span></div>`).join('')||'<p class="muted small">暂无消息</p>',link('全部 ›','notifications'))}</div></div>`;};
function typeCard(t){const b=t.published.basic;return `<button class="ga-type" data-action="go" data-to="apply/${t.id}"><span class="ga-type-icon ${esc(b.category)}">${icon(b.category==='finance'?'list':b.category==='business'?'org':'rule')}</span><span><strong>${esc(b.name)}</strong>${!mobile?`<small>${esc(b.description)}</small>`:''}</span></button>`;}
A.views.catalog=function(){const types=state.templates.filter(t=>E.allowed(state,actor,t));return state.categories.map(c=>{const list=types.filter(t=>t.published.basic.category===c.id);return list.length?`<section class="panel ga-section"><div class="panel-head"><h3>${esc(c.name)}</h3><span class="muted small">${list.length} 个事项</span></div><div class="panel-body"><div class="ga-types">${list.map(typeCard).join('')}</div></div></section>`:'';}).join('')+(types.length?'':empty('暂无可发起的审批','请联系管理员配置事项的适用范围。'));};
function todoRow(r){const t=E.current(r);return `<div class="ga-work-todo"><span class="ga-type-icon">${icon(t.type==='handling'?'check':'list')}</span><div class="content"><h3>${esc(r.title)}</h3><p>${esc(personName(r.applicant))} · ${esc(companyName(r.company))} · ${esc(t.title)}</p>${A.timingStrip(r)}</div>${link(t.type==='handling'?'去办理':'去审批','detail/'+r.id,'compact primary')}</div>`;}
const due=A.due=t=>t?T.remaining(t.dueAt):'—';
function listRows(){let rs=visible(),tab=route[1]||'all';if(tab==='todo'||tab==='overdue')rs=rs.filter(r=>E.pendingFor(r,actor)&&(tab!=='overdue'||T.overdue(r)));if(tab==='mine')rs=rs.filter(r=>r.applicant===actor);if(tab==='done')rs=rs.filter(r=>r.events.some(e=>e.actor===actor&&['同意审批','完成办理','退回修改','拒绝申请','转交'].includes(e.action)));if(tab==='cc')rs=rs.filter(r=>r.steps.some(t=>t.type==='cc'&&t.status==='done'&&t.members.includes(actor)));return rs.filter(r=>(!filters.q||(r.title+r.number+personName(r.applicant)).toLowerCase().includes(filters.q.toLowerCase()))&&(!filters.status||r.status===filters.status)&&(!filters.company||r.company===filters.company)&&(!filters.template||r.templateId===filters.template)&&(!filters.from||r.createdAt>=new Date(filters.from+'T00:00:00+08:00').getTime())&&(!filters.to||r.createdAt<=new Date(filters.to+'T23:59:59+08:00').getTime())).sort((a,b)=>b.createdAt-a.createdAt);}
A.listRows=listRows;
A.requestTable=function(rs){if(mobile)return rs.map(r=>`<article class="ga-mobile-card"><div class="top"><span class="muted small">${esc(r.number)}</span>${badge(r.status)}</div><h3>${link(esc(r.title),'detail/'+r.id)}</h3><p>${esc(personName(r.applicant))} · ${esc(companyName(r.company))}</p>${A.summary?.(r)||''}<p>当前节点：${esc(E.current(r)?.title||E.STATUS[r.status])}</p>${A.timingStrip(r)}<div class="foot"><span class="muted">${date(r.createdAt)}</span>${link(r.status==='draft'&&r.applicant===actor?'继续填写':'查看详情',r.status==='draft'&&r.applicant===actor?'edit/'+r.id:'detail/'+r.id)}</div></article>`).join('');return `<div class="table-wrap"><table class="ga-table"><thead><tr><th>审批单</th><th>发起人 / 所属公司</th><th>审批类型</th><th>状态</th><th>当前节点 / 处理人</th><th>审批时限</th><th>发起时间</th><th>操作</th></tr></thead><tbody>${rs.map(r=>{const t=E.current(r);return `<tr><td class="subject">${link(esc(r.title),'detail/'+r.id)}<span class="ga-sub">${esc(r.number)}</span>${A.summary?.(r)||''}</td><td>${esc(personName(r.applicant))}<span class="ga-sub">${esc(companyName(r.company))}</span></td><td>${esc(r.snapshot?.basic.name||state.templates.find(t=>t.id===r.templateId)?.published?.basic.name)}</td><td>${badge(r.status)}</td><td>${esc(t?.title||'—')}<span class="ga-sub">${t?esc(names(t.members)):''}</span></td><td>${A.timingStrip(r)||'<span class="muted small">—</span>'}</td><td class="nowrap">${date(r.createdAt)}</td><td class="actions">${link(r.status==='draft'&&r.applicant===actor?'继续填写':'查看',r.status==='draft'&&r.applicant===actor?'edit/'+r.id:'detail/'+r.id)}</td></tr>`;}).join('')}</tbody></table></div>`;};
A.views.list=function(){const tab=route[1]||'all';if(tab!==listTab){listTab=tab;listPage=1;filters={q:'',status:'',company:'',template:'',from:'',to:''};}const rs=listRows(),pages=Math.max(1,Math.ceil(rs.length/listSize));listPage=Math.min(listPage,pages);const tabs=[['todo','待我处理'],['done','我已处理'],['mine','我发起的'],['cc','抄送我的'],['all','全部审批']];if(mobile)return mobileListView(rs,tab,pages,tabs);return `<section class="panel ga-section"><nav class="tabs" aria-label="审批列表分类">${tabs.map(([id,l])=>`<button class="${tab===id||tab==='overdue'&&id==='todo'?'active':''}" data-action="go" data-to="list/${id}">${l}</button>`).join('')}</nav><form id="list-filters" class="ga-filters"><input type="search" name="q" aria-label="搜索审批" placeholder="审批标题 / 单号 / 发起人" value="${esc(filters.q)}"><select name="status" aria-label="审批状态">${opts([['','全部状态'],...Object.entries(E.STATUS)],filters.status)}</select><select name="company" aria-label="所属公司">${opts([['','全部公司'],...state.companies.filter(c=>visible().some(r=>r.company===c.id)).map(c=>[c.id,c.short])],filters.company)}</select><select name="template" aria-label="审批类型">${opts([['','全部类型'],...state.templates.filter(t=>t.published).map(t=>[t.id,t.published.basic.name])],filters.template)}</select><input type="date" name="from" aria-label="开始日期" value="${esc(filters.from)}"><input type="date" name="to" aria-label="结束日期" value="${esc(filters.to)}"><button class="btn primary" type="submit">查询</button>${btn('重置','list-reset')}</form></section>${tab==='overdue'?'<div class="callout warn mb">当前仅展示已超时的个人待办。</div>':''}${contentModule('审批列表',`${rs.length?A.requestTable(rs.slice((listPage-1)*listSize,listPage*listSize)):empty('没有符合条件的审批','请调整筛选条件或发起新的申请。')}${PCGroupUI.pager(rs.length,listPage,listSize,'requests')}`,btn('导出','export-list')+link('＋ 发起审批','catalog','primary'))}`;};
function mobileListView(rs,tab,pages,tabs){
 const count=Object.entries(filters).filter(([k,v])=>k!=='q'&&v).length,filtered=!!filters.q||count>0;
 return `<section class="panel ga-mobile-query"><nav class="tabs" aria-label="审批列表分类">${tabs.map(([id,l])=>`<button class="${tab===id||tab==='overdue'&&id==='todo'?'active':''}" data-action="go" data-to="list/${id}">${l}</button>`).join('')}</nav><form id="mobile-list-search" class="ga-mobile-search"><div class="ga-mobile-searchbox"><button type="submit" aria-label="搜索">${icon('search')}</button><input type="search" name="q" aria-label="搜索审批" placeholder="标题、单号、发起人" value="${esc(filters.q)}" enterkeyhint="search"></div>${btn(icon('filter')+'筛选'+(count?`<span>${count}</span>`:''),'mobile-list-filter',`aria-label="筛选审批${count?'，已选 '+count+' 项':''}"`,'ga-filter-button '+(count?'is-active':''))}</form></section><div class="ga-mobile-list-meta"><span>共 ${rs.length} 条${tab==='overdue'?' · 超时待办':''}</span>${filtered?btn('清空筛选','list-reset','','quiet compact'):''}</div><section class="ga-mobile-results" aria-label="审批记录">${rs.length?A.requestTable(rs.slice((listPage-1)*listSize,listPage*listSize)):empty(filtered?'未找到相关审批':tab==='todo'?'暂无待办':'暂无审批记录','',filtered?btn('清空筛选','list-reset','','quiet blue'):link('发起审批','catalog','quiet blue'))}${pages>1?`<div class="ga-pagination">${btn('上一页','list-page',`data-delta="-1" ${listPage===1?'disabled':''}`,'compact')}<span class="page-index">${listPage}</span><span>/ ${pages}</span>${btn('下一页','list-page',`data-delta="1" ${listPage===pages?'disabled':''}`,'compact')}</div>`:''}</section>`;
}
A.forms['mobile-list-search']=f=>{filters.q=String(new FormData(f).get('q')||'').trim();listPage=1;A.render();};
A.actions['mobile-list-filter']=()=>{
 const query=$('#mobile-list-search [name=q]')?.value||'';
 A.open('筛选审批',`<input type="hidden" name="q" value="${esc(query)}"><div class="ga-mobile-filter-fields">${select('审批状态','status',[['','全部状态'],...Object.entries(E.STATUS)],filters.status)}${select('所属公司','company',[['','全部公司'],...state.companies.filter(c=>visible().some(r=>r.company===c.id)).map(c=>[c.id,c.short])],filters.company)}${select('审批类型','template',[['','全部类型'],...state.templates.filter(t=>t.published).map(t=>[t.id,t.published.basic.name])],filters.template)}<div class="ga-mobile-filter-dates">${input('开始日期','from',filters.from,'','date')}${input('结束日期','to',filters.to,'','date')}</div></div>`,f=>{
  const v=Object.fromEntries(new FormData(f));E.assert(!v.from||!v.to||v.from<=v.to,'开始日期不能晚于结束日期');filters=v;listPage=1;A.close();A.render();
 },{saveText:'确定筛选',footer:btn('重置','mobile-filter-reset','','quiet')});
};
A.actions['mobile-filter-reset']=()=>{const f=$('#modal-form');for(const name of ['q','status','company','template','from','to'])f.elements[name].value='';$('#modal-error').textContent='';};
A.forms['list-filters']=f=>{const v=Object.fromEntries(new FormData(f));E.assert(!v.from||!v.to||v.from<=v.to,'开始日期不能晚于结束日期');filters=v;listPage=1;A.render();};
A.setListPage=(page,size)=>{listPage=page;listSize=size;A.render();};
A.actions['list-reset']=()=>{filters={q:'',status:'',company:'',template:'',from:'',to:''};listPage=1;A.render();};A.actions['list-page']=b=>{listPage+=Number(b.dataset.delta);A.render();};
A.exportCSV=function(filename,rows){const quote=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const blob=new Blob(['\ufeff'+rows.map(r=>r.map(quote).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
A.actions['export-list']=()=>{A.exportCSV('集团审批列表.csv',[['审批单号','标题','发起人','公司','状态','金额','发起时间'],...listRows().filter(r=>E.canExport(state,actor,r)).map(r=>[r.number,r.title,personName(r.applicant),companyName(r.company),E.STATUS[r.status],r.values.amount||'',date(r.createdAt)])]);A.toast('已导出当前筛选范围的审批列表');};
A.fieldControls=function(schema,values,{preview=false}={}){return schema.map(f=>{const value=values[f.id]??'',name='f:'+f.id;let control='';if(['text','number','money','date'].includes(f.type))control=f.totalFrom?`<div class="ga-field-value" data-computed="${f.id}">${money(value)}</div>`:`<input name="${name}" aria-label="${esc(f.label)}" value="${esc(value)}" type="${f.type==='money'?'number':f.type==='text'?'text':f.type}" ${['money','number'].includes(f.type)?'min="0" step="0.01"':''} placeholder="${esc(f.placeholder||'请输入'+f.label)}">`;
 if(f.type==='textarea')control=`<textarea name="${name}" aria-label="${esc(f.label)}" placeholder="${esc(f.placeholder||'请输入'+f.label)}">${esc(value)}</textarea>`;
 if(['select','person','department'].includes(f.type)){const rows=f.type==='select'?f.options.map(v=>[v,v]):f.type==='person'?state.people.filter(p=>p.active).map(p=>[p.id,p.name+' · '+p.title]):state.departments.map(d=>[d.id,companyName(d.company)+' / '+d.name]);control=`<select name="${name}" aria-label="${esc(f.label)}">${opts([['','请选择'],...rows],value)}</select>`;}
 if(f.type==='table'){const rows=Array.isArray(value)&&value.length?value:[{item:'',quantity:1,price:''}];control=`<div class="table-wrap"><table class="ga-table-input"><thead><tr><th>名称</th><th>数量</th><th>单价</th><th></th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td class="item"><input name="${name}:${i}:item" aria-label="${esc(f.label)}名称${i+1}" value="${esc(r.item)}" placeholder="名称 / 规格"></td><td><input type="number" min="0.01" step="0.01" name="${name}:${i}:quantity" aria-label="${esc(f.label)}数量${i+1}" value="${esc(r.quantity)}"></td><td><input type="number" min="0" step="0.01" name="${name}:${i}:price" aria-label="${esc(f.label)}单价${i+1}" value="${esc(r.price)}"></td><td>${btn('×',preview?'preview-table-remove':'table-remove',`data-field="${f.id}" data-index="${i}" aria-label="删除明细${i+1}"`,'quiet compact')}</td></tr>`).join('')}</tbody></table></div>${btn('＋ 添加明细',preview?'preview-table-add':'table-add',`data-field="${f.id}"`,'quiet compact blue')}`;}
 if(f.type==='attachment')control=`<label class="upload-label">${icon('plus')}上传附件<input type="file" multiple data-upload="${f.id}" aria-label="${esc(f.label)}" ${preview?'disabled':''}></label><small class="ga-helper">单个文件不超过 1 MB，总计不超过 3 MB</small><div class="ga-upload-list">${(Array.isArray(value)?value:[]).map((v,i)=>`<div class="ga-upload-item"><a href="${esc(safeData(v.data))}" download="${esc(v.name)}">${esc(v.name)}</a><span class="muted">${Math.ceil(v.size/1024)} KB</span>${btn('×','file-remove',`data-field="${f.id}" data-index="${i}" aria-label="移除附件"`,'quiet compact')}</div>`).join('')}</div>`;
 return `<div class="field ${['textarea','table','attachment'].includes(f.type)?'ga-full':''}" data-field-wrap="${f.id}" ${E.shown(f,values)?'':'hidden'}><span class="ga-field-title">${f.required?'<span class="ga-required">*</span>':''}${esc(f.label)}</span>${control}${f.help?`<small>${esc(f.help)}</small>`:''}</div>`;}).join('');};
function safeData(data){return /^data:/.test(data||'')?data:'#';}
A.readFields=function(form,schema,previous={}){const v=E.clone(previous);for(const f of schema){if(f.totalFrom||f.type==='attachment')continue;if(f.type==='table'){const inputs=[...form.querySelectorAll('input')].filter(el=>el.name.startsWith('f:'+f.id+':')&&el.name.endsWith(':item'));v[f.id]=inputs.map(el=>{const prefix=el.name.slice(0,-4);return {item:el.value,quantity:form.elements[prefix+'quantity']?.value||'',price:form.elements[prefix+'price']?.value||''};});}else if(form.elements['f:'+f.id])v[f.id]=form.elements['f:'+f.id].value;}return E.valuesFor({fields:schema},v);};
A.captureApplication=function(){const f=$('#apply-form');if(!f||!applicationDraft)return;applicationDraft.title=f.elements.title?.value||applicationDraft.title;applicationDraft.company=f.elements.company.value;applicationDraft.department=f.elements.department.value;applicationDraft.values=A.readFields(f,E.selectionFields(applicationDraft.schema),applicationDraft.values);};
function applyView(){const editing=route[0]==='edit',r=editing?state.requests.find(r=>r.id===route[1]):null,u=E.person(state,actor),t=state.templates.find(t=>t.id===(editing?r?.templateId:route[1]));if(editing&&(!r||r.applicant!==actor||!['draft','returned'].includes(r.status)))return deny();if(!t||!editing&&!E.allowed(state,actor,t))return deny();const key=route.join('/')+actor;if(applicationDraft?.key!==key)applicationDraft={key,id:r?.id,templateId:t.id,company:r?.company||u.company,department:r?.department||u.department,title:r?.title||t.published.basic.name,values:E.clone(r?.values||{}),schema:E.clone(r?.snapshot||t.published)};const d=applicationDraft;d.values=E.valuesFor(d.schema,d.values);const appointments=u.appointments||[{company:u.company,department:u.department}],companies=[...new Set(appointments.map(a=>a.company))];return `<div class="ga-page-nav">${link('‹ 返回','list/mine')}<span>集团审批 / ${editing?'修改申请':'发起审批'}</span></div>`+(r?.status==='returned'?`<div class="callout warn mb">退回原因：${esc([...r.events].reverse().find(e=>e.action==='退回修改')?.note)}。修改后将按本次流程版本重新审批。</div>`:'')+`<div class="ga-grid"><section class="panel"><form id="apply-form" novalidate><div class="ga-form-section"><h3>申请信息</h3><div id="apply-error" class="form-error callout error" role="alert"></div><div class="ga-form-grid"><div class="ga-full">${d.schema.settings.titleMode==='auto'?'<p class="ga-helper">申请标题将在提交时按表单规则自动生成。</p>':input('申请标题','title',d.title,'required maxlength="80"')}</div>${select('所属公司','company',companies.map(c=>[c,companyName(c)]),d.company)}${select('申请部门','department',appointments.filter(a=>a.company===d.company).map(a=>[a.department,deptName(a.department)]),d.department)}</div></div><div class="ga-form-section"><h3>表单内容</h3><div class="ga-form-grid">${A.fieldControls(E.selectionFields(d.schema),d.values)}</div></div><footer class="form-actions ga-sticky">${btn('预览流程','apply-preview')}${r?.status!=='returned'?btn('保存草稿','apply-save'):''}<button type="submit" class="btn primary">${r?.status==='returned'?'修改后重新提交':'提交申请'}</button></footer></form></section>${!mobile?`<div class="stack">${panel('申请说明',`<p class="detail-text">${esc(d.schema.basic.description)}</p><div class="mt small muted">发起人：${esc(u.name)}<br>流程版本：V${d.schema.version}<br>提交后可在“我发起的”查看进度。</div>`)}${panel('审批流程',`<p class="small muted">填写申请信息后，可预览匹配的审批路径与具体处理人。</p><div class="mt">${btn('预览审批路径','apply-preview','','compact')}</div>`)}</div>`:''}</div>`;}
A.views.apply=applyView;A.views.edit=applyView;
function fieldDisplay(f,v){if(v==null||v===''||Array.isArray(v)&&!v.length)return '<span class="muted">—</span>';if(f.type==='money')return money(v);if(f.type==='person')return esc(personName(v));if(f.type==='department')return esc(deptName(v));if(f.type==='table')return `<div class="table-wrap"><table><thead><tr><th>名称</th><th>数量</th><th>单价</th><th>小计</th></tr></thead><tbody>${v.map(r=>`<tr><td>${esc(r.item)}</td><td>${esc(r.quantity)}</td><td>${money(r.price)}</td><td>${money(Number(r.quantity)*Number(r.price))}</td></tr>`).join('')}</tbody></table></div>`;if(f.type==='attachment')return v.map(x=>`<a href="${esc(safeData(x.data))}" download="${esc(x.name)}">${esc(x.name)}</a>`).join('<br>');return esc(v);}
A.displayFields=(schema,values)=>`<div class="ga-detail-fields">${schema.filter(f=>E.shown(f,values)).map(f=>`<dl class="${['textarea','attachment','table'].includes(f.type)?'wide':''}"><dt>${esc(f.label)}</dt><dd>${fieldDisplay(f,values[f.id])}</dd></dl>`).join('')}</div>`;
A.process=function(steps,{closed=false}={}){return `<div class="ga-flow-list">${steps.map((t,i)=>`<div class="ga-step ${t.status}"><span class="ga-step-dot">${t.status==='done'?'✓':i+1}</span><strong>${esc(t.title)}</strong>${t.status==='active'?` ${badge('active',t.type==='handling'?'办理中':'审批中')}`:''}<div class="ga-people">${t.members.map(p=>`<span class="ga-person-chip ${t.approvals?.some(a=>a.person===p)?'done':''}">${esc(personName(p))}${t.approvals?.some(a=>a.person===p)?' ✓':''}</span>`).join('')}</div><p>${t.type==='cc'?'抄送':E.MODE[t.mode]||''}${t.status==='active'?' · '+due(t):t.status==='done'?' · '+date(t.finishedAt)+(t.dueAt&&t.finishedAt>t.dueAt?' · 超时完成':''):t.status==='skipped'?' · '+esc(t.skipReason):t.status==='returned'?' · 已退回':t.status==='rejected'?' · 已拒绝':t.status==='cancelled'?' · 已取消':closed?' · 未执行':' · 待流转'+(t.type!=='cc'?'（'+(T.node(t).enabled?'时限 '+T.duration(t.hours):'不限时')+'）':'')}</p></div>`).join('')}</div>`;};
A.previewPlan=function(schema,ctx){const result=E.plan(state,schema,ctx);A.open('审批路径预览',`${result.decisions.length?`<div class="callout mb">${result.decisions.map(d=>esc(d.node)+'：'+esc(d.branch)).join('<br>')}</div>`:''}<section class="panel">${A.process(result.tasks.map(t=>({...t,status:t.status==='skipped'?'skipped':'waiting'})))}</section><p class="ga-helper mt">以上按当前表单和任职匹配，实际审批人将在提交时确定。</p>`);};
A.actions['apply-preview']=()=>{A.captureApplication();const d=applicationDraft;const values=E.validateValues(d.schema,d.values);A.previewPlan(d.schema,{applicant:actor,company:d.company,department:d.department,values});};
async function saveApplication(saveOnly){A.captureApplication();const data=E.clone(applicationDraft);const r=await A.mutate(s=>E.submit(s,actor,data,saveOnly));applicationDraft=null;A.go(saveOnly?'list/mine':'detail/'+r.id);A.toast(saveOnly?'草稿已保存':'申请已提交，待办已生成');}
A.actions['apply-save']=()=>saveApplication(true);A.forms['apply-form']=()=>saveApplication(false);
A.actions['table-add']=b=>{A.captureApplication();const id=b.dataset.field;applicationDraft.values[id]=[...(applicationDraft.values[id]||[]),{item:'',quantity:1,price:''}];applicationDraft.dirty=true;A.render();};
A.actions['table-remove']=b=>{A.captureApplication();applicationDraft.values[b.dataset.field].splice(Number(b.dataset.index),1);applicationDraft.dirty=true;A.render();};A.actions['file-remove']=b=>{A.captureApplication();applicationDraft.values[b.dataset.field].splice(Number(b.dataset.index),1);applicationDraft.dirty=true;A.render();};
A.views.detail=function(){const r=state.requests.find(r=>r.id===route[1]);if(!r||!E.canView(state,actor,r))return deny();if(r.status==='draft'){const own=r.applicant===actor,schema=r.snapshot||state.templates.find(t=>t.id===r.templateId)?.published;return `<section class="panel"><div class="ga-detail-head"><div class="spacer"><h2>${esc(r.title)}</h2><div class="ga-detail-meta">${esc(personName(r.applicant))} · ${esc(companyName(r.company))} / ${esc(deptName(r.department))}<br>${esc(r.number)} · ${date(r.createdAt)}</div></div>${badge(r.status)}</div>${A.displayFields(schema?.fields||[],r.values)}${own?`<footer class="ga-detail-action">${link('继续填写','edit/'+r.id,'primary')}</footer>`:''}</section>`;}const t=E.current(r),own=r.applicant===actor,can=E.pendingFor(r,actor),settings=r.snapshot.settings;let actions='';if(can){if(Object.values(t.fieldPermissions||{}).includes('edit'))actions+=btn('修改表单','oa-edit-fields',`data-id="${r.id}"`);if(settings.allowAddSign)actions+=btn('加签','oa-addsign',`data-id="${r.id}"`);actions+=settings.allowTransfer!==false&&t.allowTransfer!==false?btn('转交','request-action',`data-id="${r.id}" data-kind="transfer"`):'';actions+=settings.allowReturn!==false&&t.allowReturn!==false?btn('退回修改','request-action',`data-id="${r.id}" data-kind="return"`):'';actions+=btn('拒绝','request-action',`data-id="${r.id}" data-kind="reject"`,'danger');actions+=btn(t.type==='handling'?'完成办理':'同意','request-action',`data-id="${r.id}" data-kind="${t.type==='handling'?'complete':'approve'}"`,'primary');}if(own&&t&&settings.allowUrge!==false)actions+=btn('催办','request-action',`data-id="${r.id}" data-kind="urge"`);if(own&&['pending','handling','returned'].includes(r.status)&&settings.allowWithdraw!==false)actions+=btn('撤回','request-action',`data-id="${r.id}" data-kind="withdraw"`);if(own&&r.status==='returned')actions+=link('修改并重新提交','edit/'+r.id,'primary');if(own&&['rejected','withdrawn','approved'].includes(r.status))actions+=btn('再次申请','reapply',`data-id="${r.id}"`);
 return `<div class="ga-page-nav">${link('‹ 返回审批列表','list/all')}<span>${esc(r.number)}</span><span class="spacer"></span>${!mobile?btn('打印','print','','quiet compact'):''}</div><div class="ga-grid ga-detail-layout"><div class="stack"><section class="panel"><div class="ga-detail-head"><span class="ga-type-icon">${icon('list')}</span><div class="spacer"><h2>${esc(r.title)}</h2><div class="ga-detail-meta">${esc(personName(r.applicant))} · ${esc(companyName(r.company))} / ${esc(deptName(r.department))}<br>${esc(r.number)} · ${date(r.submittedAt)} · 第 ${r.round} 次提交</div></div>${badge(r.status)}</div>${T.OPEN.includes(r.status)?`<div class="ga-detail-timebar">${A.timingStrip(r)}</div>`:''}${['returned','rejected','withdrawn'].includes(r.status)?`<div class="panel-body"><div class="callout ${r.status==='returned'?'warn':'error'}">${esc([...r.events].reverse().find(e=>['退回修改','拒绝申请','撤回申请'].includes(e.action))?.note||E.STATUS[r.status])}</div></div>`:''}${A.displayFields(r.snapshot.fields,r.values,{request:r})}${actions?`<footer class="ga-detail-action ga-sticky"><span class="muted">${can?esc(t.title):'申请操作'}</span>${actions}</footer>`:''}</section>${panel('操作记录',`<div class="timeline">${[...r.events].reverse().map(e=>`<div class="record"><h3>${esc(personName(e.actor))} · ${esc(e.action)}</h3><p>${esc(e.note||'—')}</p><small>${date(e.at)} · 第 ${e.round} 轮</small></div>`).join('')}</div>`)}</div><div class="stack">${A.timingPanel(r)}<section class="panel"><div class="panel-head"><h3>审批过程</h3><span class="muted small">V${r.snapshot.version}</span></div>${A.process(r.steps,{closed:!['pending','handling'].includes(r.status)})}</section>${r.submissions?.length?panel('历史提交',r.submissions.map(h=>btn('第 '+h.round+' 次提交 · '+date(h.submittedAt),'submission-history',`data-id="${r.id}" data-round="${h.round}"`,'quiet compact blue')).join('')):''}${r.decisions?.length?panel('条件匹配',r.decisions.map(d=>`<div class="ga-section"><span class="small muted">${esc(d.node)}</span><p class="small">${esc(d.branch)}</p></div>`).join('')):''}</div></div>`;};
A.actions['submission-history']=b=>{const r=state.requests.find(r=>r.id===b.dataset.id);E.assert(r&&E.canView(state,actor,r),'无权查看此申请');const h=r.submissions.find(h=>h.round===Number(b.dataset.round));E.assert(h,'未找到历史提交');A.open('第 '+h.round+' 次提交',`<section class="panel"><div class="panel-head"><h3>${esc(h.title)}</h3><span class="muted small">${date(h.submittedAt)}</span></div>${A.displayFields(r.snapshot.fields,h.values,{request:r})}</section><section class="panel mt"><div class="panel-head"><h3>当次审批过程</h3></div>${A.process(h.steps,{closed:true})}</section>`,null,{wide:true});};
A.actions['request-action']=b=>{const r=state.requests.find(r=>r.id===b.dataset.id),kind=b.dataset.kind,t=E.current(r),taskId=t?.id;const labels={approve:'同意审批',complete:'完成办理',return:'退回修改',reject:'拒绝申请',transfer:'转交待办',withdraw:'撤回申请',urge:'催办'};if(kind==='urge'){return A.mutate(s=>E.act(s,actor,r.id,kind)).then(()=>{A.render();A.toast('已发送催办通知');});}const body=`<div class="callout mb">${esc(r.title)}${t?' · '+esc(t.title):''}</div>${kind==='return'?'<p class="ga-helper mb">退回发起人修改；重新提交后从流程起点重新审批。</p>':''}${kind==='transfer'?select('转交给','target',[['','请选择人员'],...state.people.filter(p=>p.active&&p.id!==actor&&p.id!==r.applicant&&!t.members.includes(p.id)).map(p=>[p.id,p.name+' · '+p.title])]):''}${E.opinionTemplatesFor(t,kind).length?'<div class="oa-ref-list mb">'+E.opinionTemplatesFor(t,kind).map(note=>btn(esc(note),'oa-opinion-template',`data-note="${esc(note)}"`,'compact')).join('')+'</div>':''}${textarea(['return','reject','transfer'].includes(kind)?'<span class="ga-required">*</span>操作说明':'审批意见 / 办理说明','note','','placeholder="请填写处理意见" maxlength="1000"')}`;A.open(labels[kind],body,async f=>{const data=Object.fromEntries(new FormData(f));await A.mutate(s=>{const fresh=s.requests.find(x=>x.id===r.id);E.assert(E.current(fresh)?.id===taskId,'节点已经变化，请刷新后处理');return E.act(s,actor,r.id,kind,data);});A.close();A.render();A.toast('操作成功，审批进度已更新');},{saveText:labels[kind]});};
A.actions.reapply=b=>{const r=state.requests.find(r=>r.id===b.dataset.id),t=state.templates.find(t=>t.id===r.templateId);E.assert(r.applicant===actor&&E.allowed(state,actor,t),'当前事项不可再次申请');const routeKey='apply/'+t.id;applicationDraft={key:routeKey+actor,templateId:t.id,company:r.company,department:r.department,title:r.title,values:E.clone(r.values),schema:E.clone(t.published)};A.go(routeKey);};

A.actions['application-discard']=b=>{applicationDraft=null;A.close();A.go(b.dataset.to);};
A.actions.go=b=>{if(b.dataset.to==='host'){A.go('workbench');return;}A.go(b.dataset.to);};A.actions.close=()=>A.close();A.actions.print=()=>window.print();
A.timingStrip=function(r){if(!T.OPEN.includes(r.status))return '';const t=E.current(r),row=(label,due)=>`<span class="ga-deadline ${due&&due<=Date.now()?'red':'muted'}">${label} · ${T.remaining(due)}</span>`;return (r.totalDueAt?row('整单',r.totalDueAt):'')+(t?row('节点',t.dueAt):'');};
A.timingPanel=function(r){const t=E.current(r),p=T.overall(r.snapshot),open=T.OPEN.includes(r.status),end=r.finishedAt||Date.now(),row=(label,due,started)=>`<div class="ga-deadline-detail"><div class="row between"><strong>${label}</strong><span class="small ${due&&due<=end?'red':'blue'}">${open?T.remaining(due):due?(end>due?'超时结束':'时限内结束'):'未设置'}</span></div><p>截止：${date(due)}</p>${started?`<p>开始：${date(started)}</p>`:''}</div>`;return panel('审批时限',row('整单时限',r.totalDueAt,r.totalStartedAt)+(t?row('当前节点',t.dueAt,t.startedAt):'')+`<p class="ga-helper mt">${!r.totalDueAt?'该版本未设置整单时限。':p.returned==='restart'?'退回期间计时，重新提交时重置整单截止时间。':'退回与重新提交延续整单截止时间。'} ${t?'转交不重置节点时限。':''}</p>`);};
let checkingTimers=false;
A.checkTimers=async function(){if(checkingTimers||document.hidden||!PCGroupUI.active())return;checkingTimers=true;try{const count=await A.mutate(s=>{const n=T.sweep(s)+E.fillReminders(s);return n||{unchanged:true};});if(!modal&&!applicationDraft&&!['rule','rules','organization','apply','edit','demo'].includes(route[0])&&!document.activeElement?.matches('input,select,textarea')&&!PCUI.isPopupOpen()){const y=window.scrollY;A.render();window.scrollTo(0,y);}}catch(err){console.warn('审批提醒检查未完成：'+err.message);}finally{checkingTimers=false;}};
let booted=false;A.boot=function(){if(booted)return;booted=true;A.load();document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!PCGroupUI.owns(e.target)||!b||b.disabled)return;const fn=A.actions[b.dataset.action];if(!fn)return;try{await fn(b,e);}catch(err){if($('#modal-error'))$('#modal-error').textContent=err.message;else if($('#apply-error')){$('#apply-error').textContent=err.message;$('#apply-error').scrollIntoView({block:'center',behavior:'smooth'});}else A.toast(err.message);}});
 document.addEventListener('submit',async e=>{const f=e.target;if(!PCGroupUI.owns(f))return;if(f.id!=='modal-form'&&!A.forms[f.id])return;e.preventDefault();if(f.dataset.gaSubmitting==='true')return;f.dataset.gaSubmitting='true';const submit=f.querySelector('[type=submit]')||document.querySelector('button[type=submit][form="'+f.id+'"]');if(submit)submit.disabled=true;try{if(f.id==='modal-form'){if(modal?.onSave)await modal.onSave(f);}else await A.forms[f.id](f);}catch(err){const error=f.querySelector('.form-error');if(error){error.textContent=err.message;error.scrollIntoView({block:'nearest'});}else A.toast(err.message);}finally{delete f.dataset.gaSubmitting;if(submit)submit.disabled=false;}});
 document.addEventListener('change',async e=>{if(!PCGroupUI.owns(e.target))return;try{if(e.target.matches('input[data-action]'))await A.actions[e.target.dataset.action]?.(e.target,e);if(e.target.matches('[data-upload]')){A.captureApplication();const files=[...e.target.files],field=e.target.dataset.upload;E.assert(files.every(f=>f.size<=1024*1024),'单个附件不能超过 1 MB');const existing=applicationDraft.values[field]||[],allSize=Object.values(applicationDraft.values).flat().filter(x=>x?.data).reduce((n,x)=>n+x.size,0);E.assert(allSize+files.reduce((n,f)=>n+f.size,0)<=3*1024*1024,'附件总大小不能超过 3 MB');const data=await Promise.all(files.map(file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({name:file.name,size:file.size,type:file.type,data:reader.result});reader.onerror=()=>reject(Error('文件读取失败'));reader.readAsDataURL(file);})));const fieldSchema=applicationDraft.schema.fields.find(f=>f.id===field);E.F.validateField({...fieldSchema,required:false},[...existing,...data]);applicationDraft.values[field]=[...existing,...data];applicationDraft.dirty=true;A.render();}if(e.target.closest('#apply-form')){A.captureApplication();applicationDraft.dirty=true;if(e.target.name==='company'){applicationDraft.department=E.person(state,actor).appointments.find(a=>a.company===applicationDraft.company)?.department;A.render();}}await A.onChange?.(e);}catch(err){A.toast(err.message);}});
 document.addEventListener('input',e=>{if(!PCGroupUI.owns(e.target))return;if(e.target.closest('#apply-form')){A.captureApplication();applicationDraft.dirty=true;for(const f of applicationDraft.schema.fields){const el=document.querySelector('[data-field-wrap="'+f.id+'"]');if(el)el.hidden=!E.shown(f,applicationDraft.values);if(f.totalFrom){const target=document.querySelector('[data-computed="'+f.id+'"]');if(target)target.textContent=money(applicationDraft.values[f.id]);}}}A.onInput?.(e);});
 PCGroupStorage.subscribe(()=>{A.load();if(!PCGroupUI.active()||route[0]==='demo')return;if(modal||applicationDraft||A.isConfigEditing?.())A.toast('其他页面已更新数据，提交时将检查最新状态');else A.render();});
 document.addEventListener('visibilitychange',()=>{if(!document.hidden&&PCGroupUI.active())A.checkTimers();});};
})();

