/* Group approval business migrated from zhongtai; PC owns rendering and storage. */
(function(){
'use strict';
const A=GA,E=A.E,{esc,btn,link,badge,input,select,textarea,check,panel,opts}=A;
let orgTab='companies',orgQuery='',orgCompany='',orgPage=1,orgSize=10,statsFilter={company:'',from:'',to:''},peopleDraft=null,departmentDraft=null,noticeFilter='all';
const s=()=>A.state,actor=()=>A.actor,admin=()=>E.admin(s(),actor()),requireAdmin=()=>E.assert(admin(),'仅集团管理员可维护组织与人员'),bd=id=>`data-id="${esc(id)}"`,people=()=>s().people.filter(p=>p.active).map(p=>[p.id,p.name+' · '+p.title]),companies=()=>s().companies.map(c=>[c.id,c.short]),depts=(company)=>s().departments.filter(d=>!company||d.company===company).map(d=>[d.id,A.companyName(d.company)+' / '+d.name]);
const checks=(name,rows,selected)=>`<div class="ga-checkboxes">${rows.map(([id,nameLabel])=>`<label><input type="checkbox" name="${name}" value="${esc(id)}" ${selected.includes(id)?'checked':''}>${esc(nameLabel)}</label>`).join('')}</div>`;
const table=(headers,rows)=>`<div class="table-wrap"><table class="ga-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
A.views.organization=function(){if(!admin())return A.deny();const tabs=[['companies','公司主体'],['departments','集团组织'],['people','员工与身份'],['positions','岗位任职']],labels={companies:'新增公司',departments:'新增部门',people:'新增员工',positions:'新增岗位任职'};const list=body=>contentModule(tabs.find(([id])=>id===orgTab)[1],body,btn('＋ '+labels[orgTab],'org-new','','primary'));let content='';
 if(orgTab==='companies'){const rows=s().companies.filter(c=>(c.name+c.short+c.code).includes(orgQuery));orgPage=Math.min(orgPage,Math.max(1,Math.ceil(rows.length/orgSize)));content=list(`${table(['公司名称','公司编码','钉钉企业标识','组织部门','状态','操作'],rows.slice((orgPage-1)*orgSize,orgPage*orgSize).map(c=>`<tr><td><strong>${esc(c.name)}</strong><span class="ga-sub">${esc(c.short)}</span></td><td>${esc(c.code)}</td><td>${esc(c.corpId||'未关联')}<span class="ga-sub">${c.corpId?'演示身份映射':'待维护'}</span></td><td>${s().departments.filter(d=>d.company===c.id).length} 个</td><td>${badge(c.active?'approved':'withdrawn',c.active?'启用':'停用')}</td><td>${btn('编辑','company-edit',bd(c.id),'quiet compact blue')}${btn(c.active?'停用':'启用','company-toggle',bd(c.id),'quiet compact blue')}</td></tr>`))}${rows.length?'':A.empty('未找到公司')}${PCGroupUI.pager(rows.length,orgPage,orgSize,'organization')}`);}
 if(orgTab==='departments'){const rows=s().departments.filter(d=>(!orgCompany||d.company===orgCompany)&&(d.name+A.companyName(d.company)).includes(orgQuery));content=`<div class="ga-org-layout"><section class="panel"><div class="panel-head"><h3>集团管理组织</h3></div><div class="ga-org-tree">${btn('全部公司','org-company','data-id=""','ga-org-node '+(!orgCompany?'active':''))}${s().companies.slice(0,5).map(c=>btn(esc(c.short),'org-company',bd(c.id),'ga-org-node '+(orgCompany===c.id?'active':''))).join('')}<div class="ga-helper mt">组织按管理关系跨公司连接，申请所属公司单独记录。</div></div></section>${list(`${table(['部门','公司归属','上级管理部门','负责人','操作'],rows.map(d=>`<tr><td><strong>${esc(d.name)}</strong><span class="ga-sub">${esc(d.id)}</span></td><td>${esc(A.companyName(d.company))}</td><td>${esc(A.deptName(d.parent))}</td><td>${A.names(d.leaders)||'<span class="orange">待维护</span>'}</td><td>${btn('编辑','department-edit',bd(d.id),'quiet compact blue')}${btn('管理路径','department-path',bd(d.id),'quiet compact blue')}</td></tr>`))}${rows.length?'':A.empty('未找到部门')}`)}</div>`;}
 if(orgTab==='people'){const rows=s().people.filter(p=>(p.name+p.title+p.employeeCode).includes(orgQuery)&&(!orgCompany||p.company===orgCompany));content=list(`${table(['员工','主要任职','系统权限','钉钉身份','状态','操作'],rows.map(p=>`<tr><td><strong>${esc(p.name)}</strong><span class="ga-sub">${esc(p.employeeCode)} · ${esc(p.title)}</span></td><td>${esc(A.companyName(p.company))}<span class="ga-sub">${esc(A.deptName(p.department))}${p.appointments.length>1?' · '+p.appointments.length+' 处任职':''}</span></td><td>${{admin:'集团管理员',companyAdmin:'公司管理员',employee:'普通员工'}[p.role]}</td><td>${p.identities.length} 个主体身份<span class="ga-sub">统一内部身份</span></td><td>${badge(p.active?'approved':'withdrawn',p.active?'在职':'停用')}</td><td>${btn('编辑','person-edit',bd(p.id),'quiet compact blue')}${btn('身份映射','person-identities',bd(p.id),'quiet compact blue')}${btn(p.active?'停用':'启用','person-toggle',bd(p.id),'quiet compact blue')}</td></tr>`))}${rows.length?'':A.empty('未找到员工')}`);}
 if(orgTab==='positions'){const rows=s().positions.filter(p=>(p.name+A.names(p.members)).includes(orgQuery)&&(!orgCompany||p.company===orgCompany));content=list(`${table(['审批岗位','任职范围','任职人员','状态','操作'],rows.map(p=>`<tr><td><strong>${esc(p.name)}</strong></td><td>${esc(A.companyName(p.company))}</td><td>${esc(A.names(p.members))||'—'}</td><td>${p.members.some(id=>E.person(s(),id)?.active)?badge('approved','可匹配'):badge('returned','无人任职')}</td><td>${btn('编辑','position-edit',bd(p.id),'quiet compact blue')}</td></tr>`))}${rows.length?'':A.empty('未找到岗位')}`);}
 return `<section class="panel ga-section"><nav class="tabs">${tabs.map(([id,l])=>`<button class="${orgTab===id?'active':''}" data-action="org-tab" data-id="${id}">${l}</button>`).join('')}</nav><form class="ga-filters" id="org-filters"><input type="search" name="q" aria-label="搜索组织人员" placeholder="搜索名称 / 编码 / 人员" value="${esc(orgQuery)}">${orgTab!=='companies'?`<select name="company" aria-label="筛选公司">${opts([['','全部公司'],...companies()],orgCompany)}</select>`:''}<button type="submit" class="btn primary">查询</button>${btn('重置','org-reset')}</form></section>${content}`;
};
A.setOrgPage=(page,size)=>{orgPage=page;orgSize=size;A.render();};
A.actions['org-tab']=b=>{orgTab=b.dataset.id;orgPage=1;orgQuery='';orgCompany='';A.render();};A.actions['org-page']=b=>{orgPage+=Number(b.dataset.delta);A.render();};A.actions['org-company']=b=>{orgCompany=b.dataset.id;A.render();};A.forms['org-filters']=f=>{const d=Object.fromEntries(new FormData(f));orgQuery=d.q;orgCompany=d.company||'';orgPage=1;A.render();};A.actions['org-reset']=()=>{orgQuery='';orgCompany='';orgPage=1;A.render();};
A.actions['org-new']=()=>{if(orgTab==='companies')editCompany();if(orgTab==='departments')editDepartment();if(orgTab==='people')editPerson();if(orgTab==='positions')editPosition();};
function editCompany(id){requireAdmin();const c=s().companies.find(c=>c.id===id)||{id:E.id('company'),name:'',short:'',code:'',corpId:'',active:true};A.open(id?'编辑公司主体':'新增公司主体',`${input('公司全称','name',c.name,'maxlength="80"')}${input('公司简称','short',c.short,'maxlength="20"')}${input('公司编码','code',c.code,'maxlength="30"')}${input('钉钉企业标识（选填）','corpId',c.corpId,'placeholder="关联该主体的外部身份"')}`,async f=>{const d=Object.fromEntries(new FormData(f));for(const k of ['name','short','code'])E.assert(d[k].trim(),'请填写公司全称、简称及编码');await A.mutate(state=>{E.assert(!state.companies.some(x=>x.id!==c.id&&(x.code===d.code||x.name===d.name||d.corpId&&x.corpId===d.corpId)),'公司名称、编码或钉钉企业标识重复');const x=state.companies.find(x=>x.id===c.id);if(x)Object.assign(x,d);else state.companies.push({...c,...d});});A.close();A.render();A.toast('公司主体已保存');});}
A.actions['company-edit']=b=>editCompany(b.dataset.id);A.actions['company-toggle']=b=>{requireAdmin();const c=s().companies.find(c=>c.id===b.dataset.id);A.confirm(c.active?'停用公司主体':'启用公司主体',c.active?'停用后不能以该主体发起新申请，已有审批继续处理。':'启用后可使用该主体的有效任职发起申请。',()=>A.mutate(state=>{const x=state.companies.find(x=>x.id===c.id);x.active=!x.active;}));};
function editDepartment(id){requireAdmin();departmentDraft=E.clone(s().departments.find(d=>d.id===id)||{id:E.id('dept'),name:'',company:'hq',parent:'group',leaders:[]});const d=departmentDraft;A.open(id?'编辑组织部门':'新增组织部门',`${input('部门名称','name',d.name,'maxlength="40"')}${select('所属公司','company',companies(),d.company)}${select('上级管理部门','parent',[['','顶级部门'],...depts().filter(([id])=>id!==d.id)],d.parent||'')}<div class="field"><span class="field-title">部门负责人</span>${checks('leaders',people(),d.leaders)}</div>`,async f=>{const fd=new FormData(f),v={name:fd.get('name').trim(),company:fd.get('company'),parent:fd.get('parent')||null,leaders:fd.getAll('leaders')};E.assert(v.name,'请填写部门名称');await A.mutate(state=>{const x=state.departments.find(x=>x.id===d.id);if(x)Object.assign(x,v);else state.departments.push({...d,...v});for(const dep of state.departments)E.chain(state,dep.id);E.assert(!state.people.some(p=>p.department===d.id&&p.company!==v.company),'该部门已有员工任职，请先调整员工后变更公司');});A.close();A.render();A.toast('集团组织关系已保存');});}
A.actions['department-edit']=b=>editDepartment(b.dataset.id);A.actions['department-path']=b=>{const path=E.chain(s(),b.dataset.id);A.open('集团管理路径',`<div class="ga-flow-list">${path.map((d,i)=>`<div class="ga-step"><span class="ga-step-dot">${i+1}</span><strong>${esc(d.name)}</strong><p>${esc(A.companyName(d.company))}</p><p>负责人：${esc(A.names(d.leaders)||'未配置')}</p></div>`).join('')}</div>`);};
function editPerson(id){requireAdmin();peopleDraft=E.clone(s().people.find(p=>p.id===id)||{id:E.id('person'),name:'',employeeCode:'',title:'',company:'hq',department:'hr',role:'employee',manager:'leader',active:true,appointments:[],identities:[]});drawPerson();}
function readPerson(){const f=document.querySelector('#modal-form');if(!f)return;const fd=new FormData(f);for(const k of ['name','employeeCode','title','company','department','role','manager'])peopleDraft[k]=fd.get(k);peopleDraft.appointments=fd.getAll('appointments').map(id=>{const d=E.department(s(),id);return {department:id,company:d.company};});}
function drawPerson(){const p=peopleDraft;A.open('维护员工任职',`<div class="form-grid">${input('员工姓名','name',p.name,'maxlength="30"')}${input('内部工号','employeeCode',p.employeeCode,'maxlength="30"')}${input('岗位称谓','title',p.title,'maxlength="40"')}${select('主要任职公司','company',companies(),p.company)}${select('主要任职部门','department',depts(p.company),p.department)}${select('直属上级','manager',[['','无'],...people().filter(([id])=>id!==p.id)],p.manager||'')}${select('系统权限','role',[['employee','普通员工'],['companyAdmin','公司管理员'],['admin','集团管理员']],p.role)}</div><div class="mt field"><span class="field-title">其他兼任部门（选填）</span>${checks('appointments',depts().filter(([id])=>id!==p.department),p.appointments.map(a=>a.department))}</div><p class="ga-helper">公司管理员仅查看主要任职公司及本人参与的审批。身份映射在员工列表单独维护。</p>`,async()=>{readPerson();E.assert(p.name?.trim()&&p.employeeCode?.trim()&&p.title?.trim(),'请填写姓名、工号和岗位称谓');E.assert(E.department(s(),p.department)?.company===p.company,'请选择有效任职部门');const appointments=[{company:p.company,department:p.department},...p.appointments.filter(a=>a.department!==p.department)];await A.mutate(state=>{E.assert(!state.people.some(x=>x.id!==p.id&&x.employeeCode===p.employeeCode),'内部工号重复');E.assert(!(p.id===actor()&&p.role!=='admin'),'请通过另一位集团管理员调整自己的管理权限');const x=state.people.find(x=>x.id===p.id);if(x)Object.assign(x,p,{appointments});else state.people.push({...p,appointments});for(const person of state.people){let next=person,seen=new Set();while(next){E.assert(!seen.has(next.id),'直属上级关系存在循环');seen.add(next.id);next=E.person(state,next.manager);}}});A.close();A.render();A.toast('员工与任职已保存');},{wide:true});}
A.actions['person-edit']=b=>editPerson(b.dataset.id);A.actions['person-toggle']=b=>{requireAdmin();const p=E.person(s(),b.dataset.id);A.confirm(p.active?'停用员工':'启用员工',p.active?'停用前须转交该员工尚未完成的待办，避免审批中断。':'启用后该员工可以继续参与审批。',()=>A.mutate(state=>{const x=E.person(state,p.id);E.assert(x.id!==actor(),'不能停用当前登录身份');if(x.active)E.assert(!state.requests.some(r=>['pending','handling'].includes(r.status)&&r.steps.some(t=>['active','waiting'].includes(t.status)&&t.members.includes(x.id))),'该员工仍有当前或后续待办，请先完成或转交');x.active=!x.active;}));};
let identityPerson=null,identityRows=[];
function readIdentities(){const f=document.querySelector('#modal-form');if(!f)return;identityRows=identityRows.map((x,i)=>({company:f.elements['company:'+i].value,userId:f.elements['userId:'+i].value.trim()}));}
function drawIdentities(){A.open('员工身份映射',`<div class="callout mb">${esc(identityPerson.name)} · ${esc(identityPerson.employeeCode)}<br>同一个内部员工可以关联多个钉钉企业身份。企业标识与用户标识共同定位外部账号。</div>${identityRows.map((x,i)=>`<div class="ga-condition-row" style="grid-template-columns:1fr 1fr 28px"><select name="company:${i}" aria-label="身份所属公司">${opts(companies(),x.company)}</select><input name="userId:${i}" aria-label="钉钉用户标识" value="${esc(x.userId)}" placeholder="钉钉用户标识">${btn('×','identity-remove',`data-index="${i}" aria-label="移除身份"`,'quiet compact')}</div>`).join('')}${btn('＋ 添加主体身份','identity-add','','quiet blue')}<p class="ga-helper mt">本页演示映射维护，不进行真实钉钉账号验证。</p>`,async()=>{readIdentities();E.assert(identityRows.every(x=>x.userId),'请填写钉钉用户标识');const keys=identityRows.map(x=>x.company+':'+x.userId);E.assert(new Set(keys).size===keys.length,'存在重复身份');await A.mutate(state=>{E.assert(!state.people.some(p=>p.id!==identityPerson.id&&p.identities.some(i=>keys.includes(i.company+':'+i.userId))),'该企业身份已关联其他员工');E.person(state,identityPerson.id).identities=E.clone(identityRows);});A.close();A.render();A.toast('跨主体身份映射已保存');});}
A.actions['person-identities']=b=>{requireAdmin();identityPerson=E.clone(E.person(s(),b.dataset.id));identityRows=E.clone(identityPerson.identities);drawIdentities();};A.actions['identity-add']=()=>{readIdentities();identityRows.push({company:'hq',userId:''});drawIdentities();};A.actions['identity-remove']=b=>{readIdentities();identityRows.splice(Number(b.dataset.index),1);drawIdentities();};
function editPosition(id){requireAdmin();const p=E.clone(s().positions.find(p=>p.id===id)||{id:E.id('position'),name:'',company:'hq',members:[]});A.open(id?'编辑岗位任职':'新增岗位任职',input('岗位名称','name',p.name,'placeholder="如：财务负责人" maxlength="40"')+select('任职范围','company',companies(),p.company)+`<div class="field"><span class="field-title">任职人员</span>${checks('members',people(),p.members)}</div><p class="ga-helper">流程选择“所属公司岗位”时匹配申请公司；选择“集团岗位”时匹配集团总部任职。</p>`,async f=>{const fd=new FormData(f),v={name:fd.get('name').trim(),company:fd.get('company'),members:fd.getAll('members')};E.assert(v.name&&v.members.length,'请填写岗位名称并选择任职人员');await A.mutate(state=>{E.assert(!state.positions.some(x=>x.id!==p.id&&x.name===v.name&&x.company===v.company),'该公司已配置同名岗位，请编辑已有任职');const x=state.positions.find(x=>x.id===p.id);if(x)Object.assign(x,v);else state.positions.push({...p,...v});});A.close();A.render();A.toast('岗位任职已保存');});}
A.actions['position-edit']=b=>editPosition(b.dataset.id);
function statRows(){return A.visible().filter(r=>r.status!=='draft'&&(!statsFilter.company||r.company===statsFilter.company)&&(!statsFilter.from||r.createdAt>=new Date(statsFilter.from+'T00:00:00+08:00').getTime())&&(!statsFilter.to||r.createdAt<=new Date(statsFilter.to+'T23:59:59+08:00').getTime()));}
function chart(rows,max){return rows.map(([label,value])=>`<div class="ga-chart-row"><span>${esc(label)}</span><div class="ga-bar"><span style="width:${max?value/max*100:0}%"></span></div><span class="muted">${value}</span></div>`).join('');}
A.views.statistics=function(){const rows=statRows(),done=rows.filter(r=>r.status==='approved'),active=rows.filter(r=>E.T.OPEN.includes(r.status)),over=active.filter(r=>E.T.overdue(r)),avg=done.length?done.reduce((n,r)=>n+(r.finishedAt-r.submittedAt)/3600000,0)/done.length:0,typeRows=s().templates.filter(t=>t.published).map(t=>[t.published.basic.name,rows.filter(r=>r.templateId===t.id).length]),companyRows=companies().map(([id,name])=>[name,rows.filter(r=>r.company===id).length]).filter(([,n])=>n),load=s().people.map(p=>({person:p,requests:active.filter(r=>E.pendingFor(r,p.id)),handled:rows.filter(r=>r.events.some(e=>e.actor===p.id&&['同意审批','完成办理'].includes(e.action))).length})).filter(x=>x.requests.length||x.handled).sort((a,b)=>b.requests.length-a.requests.length);
 return `<section class="panel ga-section"><form class="ga-filters" id="stats-filters"><select name="company" aria-label="统计公司">${opts([['','全部可见公司'],...companies().filter(([id])=>A.visible().some(r=>r.company===id))],statsFilter.company)}</select><input type="date" name="from" aria-label="统计开始日期" value="${statsFilter.from}"><span class="muted small">至</span><input type="date" name="to" aria-label="统计结束日期" value="${statsFilter.to}"><button class="btn primary" type="submit">查询</button>${btn('重置','stats-reset')}</form></section>${contentModule('审批概况',`<div class="panel-body"><div class="ga-summary">${[['发起审批',rows.length,'不含草稿','blue'],['办结率',rows.length?(done.length/rows.length*100).toFixed(1)+'%':'—','已办结 / 发起审批','green'],['平均办结时长',done.length?avg.toFixed(1)+'h':'—','按已办结申请计算',''],['当前超时审批',over.length,'整单或节点到期，按单去重','red']].map(([l,v,d,c])=>`<div class="stat"><span class="muted small">${l}</span><strong class="${c}">${v}</strong><small>${d}</small></div>`).join('')}</div></div>`,btn('导出统计','export-stats'))}<div class="ga-grid ga-section">${panel('审批类型分布',chart(typeRows,Math.max(...typeRows.map(x=>x[1]),1)))}${panel('公司申请分布',companyRows.length?chart(companyRows,Math.max(...companyRows.map(x=>x[1]),1)):A.empty('暂无数据'))}</div><section class="panel"><div class="panel-head"><h3>处理人待办与效率</h3><span class="muted small">多人审批分别计入各处理人待办</span></div>${table(['处理人','所属公司','当前待办','超时待办','已处理审批'],load.map(x=>`<tr><td>${esc(x.person.name)}<span class="ga-sub">${esc(x.person.title)}</span></td><td>${esc(A.companyName(x.person.company))}</td><td>${x.requests.length}</td><td class="${x.requests.some(r=>E.T.overdue(r))?'red':''}">${x.requests.filter(r=>E.T.overdue(r)).length}</td><td>${x.handled}</td></tr>`))}${load.length?'':A.empty('暂无处理记录')}</section>`;
};
A.forms['stats-filters']=f=>{const v=Object.fromEntries(new FormData(f));E.assert(!v.from||!v.to||v.from<=v.to,'开始日期不能晚于结束日期');statsFilter=v;A.render();};A.actions['stats-reset']=()=>{statsFilter={company:'',from:'',to:''};A.render();};A.actions['export-stats']=()=>{const rows=statRows();A.exportCSV('集团审批统计.csv',[['审批单号','公司','事项','状态','发起时间','办结时间','办结时长（小时）'],...rows.map(r=>[r.number,A.companyName(r.company),r.snapshot.basic.name,E.STATUS[r.status],A.date(r.submittedAt),A.date(r.finishedAt),r.status==='approved'?((r.finishedAt-r.submittedAt)/3600000).toFixed(1):''])]);A.toast('统计明细已导出');};
A.views.notifications=function(){const rows=s().notifications.filter(n=>n.person===actor()&&(noticeFilter!=='unread'||!n.read));const tabs=`<nav class="tabs">${[['all','全部消息'],['unread','未读消息']].map(([id,l])=>`<button class="${id===noticeFilter?'active':''}" data-action="notice-tab" data-id="${id}">${l}</button>`).join('')}</nav>`;const body=rows.map(n=>`<div class="ga-notice ${n.read?'read':''}"><span class="dot"></span><div class="content"><h3>${btn(esc(n.title),'notice-open',bd(n.id),'quiet compact blue')}</h3><span class="ga-sub">${A.date(n.at)} · ${n.read?'已读':'未读'}</span></div>${!n.read?btn('已读','notice-read',bd(n.id),'quiet compact'):''}</div>`).join('')||A.empty('暂无消息',A.mobile?'':'新的审批待办和办理结果会显示在这里。');return A.mobile?`<section class="panel">${tabs}${body}</section>`:`<section class="panel ga-section">${tabs}</section>`+contentModule('消息通知',body,btn('全部标为已读','notice-read-all'));};
A.actions['notice-tab']=b=>{noticeFilter=b.dataset.id;A.render();};A.actions['notice-read-all']=async()=>{await A.mutate(state=>state.notifications.filter(n=>n.person===actor()).forEach(n=>n.read=true));A.render();A.toast('全部消息已标为已读');};A.actions['notice-read']=async b=>{await A.mutate(state=>{const n=state.notifications.find(n=>n.id===b.dataset.id&&n.person===actor());E.assert(n,'消息不存在');n.read=true;});A.render();};A.actions['notice-open']=async b=>{const n=s().notifications.find(n=>n.id===b.dataset.id&&n.person===actor());E.assert(n,'消息不存在');if(n.kind==='fill-reminder'){await A.mutate(state=>{state.notifications.find(x=>x.id===n.id).read=true;});A.go('apply/'+n.templateId);return;}const r=s().requests.find(r=>r.id===n.request);E.assert(r&&E.canView(s(),actor(),r),'该申请已不可见');await A.mutate(state=>{state.notifications.find(x=>x.id===n.id).read=true;});A.go('detail/'+n.request);};
A.views.profile=function(){const p=E.person(s(),actor()),mine=s().requests.filter(r=>r.applicant===actor());return panel('我的信息',`<div class="ga-person-profile"><span class="avatar">${esc(p.name[0])}</span><div><h2>${esc(p.name)}</h2><p class="muted small">${esc(p.title)}</p></div></div><ul class="line-list mt"><li><label>主要任职公司</label><strong>${esc(A.companyName(p.company))}</strong></li><li><label>任职部门</label><strong>${esc(A.deptName(p.department))}</strong></li><li><label>统一员工号</label><strong>${esc(p.employeeCode)}</strong></li><li><label>关联主体身份</label><strong>${p.identities.length} 个</strong></li></ul>`)+`<section class="panel mt">${[['我发起的','list/mine',mine.length],['待我处理','list/todo',s().requests.filter(r=>E.pendingFor(r,actor())).length],['抄送我的','list/cc',s().requests.filter(r=>r.steps.some(t=>t.type==='cc'&&t.status==='done'&&t.members.includes(actor()))).length],['消息通知','notifications',s().notifications.filter(n=>n.person===actor()&&!n.read).length]].map(([l,to,n])=>`<div class="ga-work-todo"><span class="content">${l}</span><span class="muted small">${n}</span>${link('›',to)}</div>`).join('')}</section>`;};
A.views.demo=function(){const scenarios=[['采购申请与逐级审批','purchase','按申请部门匹配逐级负责人及总部采购。'],['大额报销与财务会签','expense','通过金额条件进入集团复核，再到付款办理。'],['总部行政用印','seal','部门审核、行政审核、用印办理和自动抄送。'],['业务优惠与依次审批','discount','优惠金额超授权时，进入运营、财务依次审批。'],['请假与人事登记','leave','按天数条件增加人事审核，完成登记后办结。']];return `<div class="ga-demo-grid"><div class="stack"><section class="panel"><div class="panel-head"><h3>完整业务场景</h3></div>${scenarios.map(([title,tid,desc])=>`<div class="ga-work-todo"><span class="ga-type-icon">${A.icon('list')}</span><div class="content"><h3>${title}</h3><p>${desc}</p></div>${btn('开始体验','demo-start',`data-template="${tid}"`,'compact')}</div>`).join('')}</section>${panel('演示方式',`<div class="ga-demo-steps">${[['1','配置事项','在规则配置中编辑表单与审批节点，并发布版本。'],['2','发起申请','填写表单并预览匹配的审批路径。'],['3','查看审批','在全部审批中查看各公司的审批进度、处理人和办理记录。'],['4','查看结果','PC、移动端共享进度，操作和消息均留痕。']].map(([n,t,d])=>`<div class="ga-demo-step"><span class="ga-demo-number">${n}</span><div><b>${t}</b><p>${d}</p></div></div>`).join('')}</div>`)}${panel('演示数据',`<p class="small muted">已预置 52 个公司主体、六类审批和多种状态。当前为浏览器本地原型，跨设备登录、钉钉推送及付款接口尚未接入。</p><div class="row mt">${admin()?btn('导出本模块数据','export-data','','compact'):''}${admin()?btn('重置演示数据','reset-data','','compact danger'):''}</div><p class="ga-helper mt">重置仅作用于集团审批模块，会清除本模块新增数据。</p>`)}</div>${contentModule('移动端预览',`<div class="ga-phone-preview"><iframe title="集团审批移动端预览" src="pc.html?groupMobile=1#group-workbench"></iframe></div><p class="ga-phone-note">404px 手机视图 · 与 PC 共用审批进度</p>`,`<a class="btn primary" href="pc.html?groupMobile=1#group-workbench" target="_blank" rel="noopener">独立打开移动端</a>`)}</div>`;};
A.actions['demo-start']=b=>A.go('apply/'+b.dataset.template);
A.actions['export-data']=()=>{requireAdmin();const url=URL.createObjectURL(new Blob([JSON.stringify(s(),null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='集团审批原型数据.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
A.actions['reset-data']=()=>{requireAdmin();A.open('重置集团审批演示数据',`<div class="callout warn mb">本模块新增申请、配置和组织修改将被清除，恢复预置示例。客诉数据不受影响。</div>${input('请输入“重置集团审批”','confirmation','','placeholder="重置集团审批"')}`,async f=>{E.assert(f.elements.confirmation.value==='重置集团审批','请输入完整确认文字');await A.mutate(state=>{const revision=state.revision,next=GroupSeed.create();Object.keys(state).forEach(k=>delete state[k]);Object.assign(state,next,{revision});});A.close();location.reload();},{saveText:'确认重置'});};
const prev=A.onChange;A.onChange=e=>{prev?.(e);if(A.modal?.title==='维护员工任职'&&e.target.name==='company'){readPerson();peopleDraft.department=s().departments.find(d=>d.company===peopleDraft.company)?.id||'';drawPerson();}};
})();

;
/* Register only the PC lifecycle; the group module never installs another shell. */
window.PCModules['group-approval'] = (() => {
  let timer,initialError;
  GA.actions['pc-page-close']=()=>GA.go(PCGroupUI.returnRoute());
  PCUI.registerPager('group-approval',(value,config)=>{
    if(config.scope==='organization')GA.setOrgPage(value.currentPage,value.pageSize);
    else GA.setListPage(value.currentPage,value.pageSize);
  });
  GA.actions['pc-upload']=button=>button.closest('.ga-upload-control').querySelector('input[type=file]').click();
  const ready=Promise.resolve().then(()=>PCGroupStorage.initialize()).then(()=>GA.boot()).catch(error=>{initialError=error;});
  return {
    ready,
    render(){
      if(initialError){document.querySelector('#main').innerHTML='<section class="panel"><div class="empty"><div>审批数据暂时无法加载</div><p>'+GA.esc(initialError.message)+'</p><button type="button" class="btn" onclick="location.reload()">重新加载</button></div></section>';return;}
      GA.enter();clearInterval(timer);timer=setInterval(()=>GA.checkTimers(),30000);
    },
    redraw(){if(!initialError)GA.render();},
    go(path,id){
      const target=path+(id?'?id='+encodeURIComponent(id):'');
      if(initialError){if(location.hash==='#'+target)location.reload();else location.hash=target;return;}
      GA.go('@'+target);
    },
    leave(){clearInterval(timer);PCGroupUI.leave();}
  };
})();
